  +  } as any);
  +  return {
  +    app,
  +    restore: () => {
  +      if (previousHome === undefined) delete process.env.HOME; else process.env.HOME = previousHome;
  +      fs.rmSync(repo, { recursive: true, force: true });
  +      fs.rmSync(home, { recursive: true, force: true });
  +    },
  +  };
  +}
  +
