    const options = commandOptions(cmd);
    let prompt = promptParts.join(" ").trim();
    const config = buildConfig(options);
    config.surface = "headless";
    const isJson = Boolean(options.json);

    // Auto-detect loaded model if model is 'local-model'
    if (config.model === "local-model") {
      try {
        const client = new LocalLlmClient(config);
        const models = await client.listModels();
        if (models.length > 0) {
          config.model = models[0];
          if (!isJson) {
            console.log(pc.dim(`🔍 Auto-detected active model: ${pc.bold(config.model)}`));
          }
        }
      } catch {
        // Fallback to default
      }
    }

    if (!isJson && (config.provider || config.plannerProvider || config.coderProvider)) console.error(pc.dim(describeTarget(config)));
    const app = new ApplicationCore(config);

    let resumeTaskId: string | undefined;
    if ((options.resume === undefined || options.resume === false) && !prompt) {
      console.error("error: missing required argument 'prompt'");
      app.shutdown();
      exitAfterFlush(1);
      return;
    }

    // Operator stop authority: first SIGINT cancels the active turn; a second one terminates immediately.
    const abort = new AbortController();
    let sigints = 0;
    const onSigint = () => {
      sigints++;
      if (sigints === 1) {
        abort.abort(new Error("SIGINT"));
        if (!isJson) console.error(pc.yellow("\nInterrupt received: no further work will be started (Ctrl-C again to terminate immediately)."));
      } else {
        process.exit(130);
      }
    };
    process.on("SIGINT", onSigint);

    try {
      if (options.resume !== undefined && options.resume !== false) {
        if (typeof options.resume === "string" && options.resume !== "latest") {
          resumeTaskId = options.resume;
        } else {
          const targetWorkspace = config.workspace || process.cwd();
          const tasks = app
            .getStateManager()
            .listTasks({ workspace: targetWorkspace })
            .filter((t) => t.taskId !== app.getTaskId());
          if (tasks.length === 0) {
            console.error(`no task to resume in ${formatCliDiagnostic(targetWorkspace)}; see 'nexus status'`);
            app.shutdown();
            exitAfterFlush(2);
            return;
          }
          resumeTaskId = tasks[0].taskId;
        }
        if (!prompt) {
          prompt = options.step ? "" : "continue";
        }
      }
      const result = await app.runTask(prompt, {
        json: isJson,
        resumeTaskId,
        signal: abort.signal,
        step: Boolean(options.step),
      });

      const cloud = UsageLedger.global().cloudTotals();
      if (isJson) {
        console.log(JSON.stringify(cloud.requests ? { ...result, cloudUsage: cloud } : result, null, 2));
      } else if (cloud.requests) {
        console.error(pc.dim(UsageLedger.global().summary()!));
      }

      app.shutdown();
      exitAfterFlush(result.exitCode);
    } catch (err: any) {
      if (isJson) {
        console.log(JSON.stringify({
          taskId: app.getTaskId(),
          success: false,
          status: "failed",
          prompt: redactDiagnosticForOutput(prompt),
          output: "",
          plan: [],
          milestones: [],
          validationReceipts: [],
          tokenStats: { prompt: 0, completion: 0, total: 0 },
          durationMs: 0,
          error: redactDiagnosticForOutput(String(err?.message ?? err)),
        }, null, 2));
      } else {
        console.error(pc.red(`\nTask failed: ${formatCliDiagnostic(err)}`));
      }
      const exitCode = (err instanceof TaskStateNotFoundError || err?.name === "TaskStateNotFoundError") ? 2 : 1;
      app.shutdown();
      exitAfterFlush(exitCode);
    }
  });

