  /** One agent turn: checkpoint, run, save the session, report the result. `step`: one cycle of the unfinished objective. */
  private async turn(turnId: string, prompt: string | any[], label: string, checkpoint: string, signal: AbortSignal, step = false): Promise<void> {
    const agent = this.app.getAgent();
    let allowSensitiveCheckpoint = false;
    if (this.app.getConfig().readOnly) {
      // Read-only turns cannot change the workspace, so a workspace rollback snapshot is unnecessary.
      agent.setCheckpointReadOnlyFallback(false);
    } else {
      let checkpointReady = false;
      while (!checkpointReady) {
        try {
          this.checkpointManager.createCheckpoint(
            checkpoint,
            allowSensitiveCheckpoint ? { allowSensitive: true } : undefined,
          );
          const previousApprovalMode = agent.getApprovalMode();
          agent.setCheckpointReadOnlyFallback(false);
          if (agent.getApprovalMode() !== previousApprovalMode) this.emitSessionState();
          checkpointReady = true;
        } catch (err) {
          const sensitiveContentBlocked = err instanceof SensitivePersistenceError;
          const failure = capText(
            formatSafeSidecarText(errorText(err))
              .replace(/\s+/g, " ")
              .trim()
              .replace(/;\s*no checkpoint was written\.?$/i, ""),
            100,
          );
          const message = sensitiveContentBlocked
            ? undefined
            : `Checkpoint failed: ${failure}. No checkpoint was written. Choose 1 read-only, 2 continue without a rollback checkpoint, 3 retry checkpoint normally, 4 canc
          const choices: readonly CheckpointChoice[] = sensitiveContentBlocked
            ? ["read_only", "without_checkpoint", "allow_sensitive", "cancel", "other"]
            : ["read_only", "without_checkpoint", "retry", "cancel", "other"];
          const choice = await this.requestCheckpointChoice(turnId, signal, message, choices);
          if (choice === "cancel" || choice === "other") {
            const message = choice === "other"
              ? "This turn was not started. Enter a different instruction in the composer."
              : "This turn was cancelled before it started.";
            this.emit({ type: "error", id: turnId, code: "INTERNAL", message });
            return;
          }
          if (choice === "read_only") {
            agent.setCheckpointReadOnlyFallback(true);
            this.emit({ type: "notice", text: "Continuing this turn in read-only mode as requested. Workspace changes, unsafe commands, external actions, and delegation a
            this.emitSessionState();
            checkpointReady = true;
          } else if (choice === "without_checkpoint") {
            const previousApprovalMode = agent.getApprovalMode();
            agent.setCheckpointReadOnlyFallback(false);
            if (agent.getApprovalMode() !== previousApprovalMode) this.emitSessionState();
            this.emit({ type: "notice", text: "Continuing in the current mode without a rollback checkpoint, as requested." });
            checkpointReady = true;
          } else if (choice === "retry") {
            this.emit({ type: "notice", text: "Retrying checkpoint without changing sensitive-persistence settings. The turn remains paused until the retry succeeds or yo
          } else if (choice === "allow_sensitive") {
            allowSensitiveCheckpoint = true;
      // Persist even if the turn threw, so the transcript of work done so far is not lost (synced: the turn ended).
      withDurableSync(() => this.saveCurrentSession(label, this.agent.getLastTurnResult()));
    }
    return result;
  }

  /** Ask before a turn when a rollback checkpoint would persist sensitive workspace content. */
  private async prepareTurnCheckpoint(name: string): Promise<boolean> {
    if (this.config.readOnly) {
      this.agent.setCheckpointReadOnlyFallback(false);
      return true;
    }

    let allowSensitive = false;
    while (true) {
      try {
        this.checkpointManager.createCheckpoint(name, allowSensitive ? { allowSensitive: true } : undefined);
        this.agent.setCheckpointReadOnlyFallback(false);
        return true;
      } catch (error) {
        const sensitiveBlocked = error instanceof SensitivePersistenceError;
        const failure = formatReplDiagnostic(error)
          .replace(/;\s*no checkpoint was written\.?$/i, "")
          .slice(0, 240) || "unknown error";
        if (sensitiveBlocked) {
          console.log(pc.yellow("Sensitive content blocked the rollback checkpoint. Choose how to continue:"));
          console.log("  1. Continue this turn read-only; return to configured mode after a safe checkpoint");
          console.log("  2. Continue in the current mode without a rollback checkpoint");
          console.log("  3. Create the checkpoint anyway (may persist sensitive content)");
          console.log("  4. Cancel this turn");
          console.log("  5. Enter a different instruction");
        } else {
          console.log(pc.yellow(`Checkpoint creation failed: ${failure}. Do not rely on a recovery checkpoint from this attempt. Choose how to continue:`));
          console.log("  1. Continue this turn read-only; return to configured mode after a safe checkpoint");
          console.log("  2. Continue in the current mode without a rollback checkpoint");
          console.log("  3. Retry checkpoint normally");
          console.log("  4. Cancel this turn");
          console.log("  5. Enter a different instruction");
        }

        while (true) {
          const choice = (await this.rl!.question("Choice [1-5]: ")).trim();
          if (choice === "1") {
            this.agent.setCheckpointReadOnlyFallback(true);
            console.log(pc.yellow("Continuing this turn in read-only mode. Your configured mode resumes after a safe checkpoint succeeds.\n"));
            return true;
          }
          if (choice === "2") {
            this.agent.setCheckpointReadOnlyFallback(false);
            console.log(pc.yellow("Continuing in the current mode without a rollback checkpoint.\n"));
            return true;
          }
